import React, { useEffect, useRef, useState } from 'react';
import './BallSimulation.css';

const BallSimulation = () => {
  const canvasRef = useRef(null);
  const animationRef = useRef(null);
  const ballsRef = useRef([]);

  // Box dimensions
  const BOX_WIDTH = 800;
  const BOX_HEIGHT = 600;
  const BALL_RADIUS = 15;

  // Initialize balls with random positions, velocities, and colors
  const initializeBalls = () => {
    const colors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FECA57'];
    const balls = [];

    for (let i = 0; i < 3; i++) {
      balls.push({
        id: i,
        x: Math.random() * (BOX_WIDTH - 2 * BALL_RADIUS) + BALL_RADIUS,
        y: Math.random() * (BOX_HEIGHT - 2 * BALL_RADIUS) + BALL_RADIUS,
        vx: (Math.random() - 0.5) * 8, // Random velocity between -4 and 4
        vy: (Math.random() - 0.5) * 8,
        color: colors[i % colors.length],
        radius: BALL_RADIUS
      });
    }

    ballsRef.current = balls;
  };

  // Update ball positions and handle wall collisions
  const updateBalls = () => {
    ballsRef.current.forEach(ball => {
      // Update position
      ball.x += ball.vx;
      ball.y += ball.vy;

      // Collision with left or right wall
      if (ball.x - ball.radius <= 0 || ball.x + ball.radius >= BOX_WIDTH) {
        ball.vx = -ball.vx;
        // Keep ball within bounds
        ball.x = Math.max(ball.radius, Math.min(BOX_WIDTH - ball.radius, ball.x));
      }

      // Collision with top or bottom wall
      if (ball.y - ball.radius <= 0 || ball.y + ball.radius >= BOX_HEIGHT) {
        ball.vy = -ball.vy;
        // Keep ball within bounds
        ball.y = Math.max(ball.radius, Math.min(BOX_HEIGHT - ball.radius, ball.y));
      }
    });
  };

  // Render balls on canvas
  const render = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    // Clear canvas
    ctx.clearRect(0, 0, BOX_WIDTH, BOX_HEIGHT);

    // Draw box border
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 3;
    ctx.strokeRect(0, 0, BOX_WIDTH, BOX_HEIGHT);

    // Draw balls
    ballsRef.current.forEach(ball => {
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fillStyle = ball.color;
      ctx.fill();
      ctx.strokeStyle = '#333';
      ctx.lineWidth = 2;
      ctx.stroke();
    });
  };

  // Animation loop
  const animate = () => {
    updateBalls();
    render();
    animationRef.current = requestAnimationFrame(animate);
  };

  // Initialize simulation when component mounts
  useEffect(() => {
    initializeBalls();
    animate();

    // Cleanup animation on unmount
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  // Reset simulation
  const resetSimulation = () => {
    initializeBalls();
  };

  return (
    <div className="ball-simulation">
      <h1>Bouncing Balls Simulation</h1>
      <div className="simulation-container">
        <canvas
          ref={canvasRef}
          width={BOX_WIDTH}
          height={BOX_HEIGHT}
          className="simulation-canvas"
        />
      </div>
      <div className="controls">
        <button onClick={resetSimulation} className="reset-button">
          Reset Simulation
        </button>
        <div className="info">
          <p>3 balls bouncing around in a box!</p>
          <p>Each ball has random starting position, direction, and speed.</p>
        </div>
      </div>
    </div>
  );
};

export default BallSimulation;
